TEST_PROPOSAL:

```js
test("concurrent identical accept-result calls produce exactly one receipt", async () => {
  const dataRoot = root();
  const o = offer("dry-run", dataRoot);
  const product = run(contract(o), "invoke-service", at, { root: dataRoot, liss: lissFixture }).object;
  const dec = decision(product, "Accept");
  const [r1, r2] = await Promise.all([
    Promise.resolve(run(dec, "accept-result", at, { root: dataRoot })),
    Promise.resolve(run(dec, "accept-result", at, { root: dataRoot })),
  ]);
  const receipts = readdirSync(join(dataRoot, "data", "records", "work-lot-receipts", "2026", "07", "18"));
  assert.equal(receipts.length, 1);
  if (r1.type === "Accept" && r2.type === "Accept") {
    assert.equal(r1.object.id, r2.object.id);
  } else {
    assert.ok(r1.type === "Accept" || r2.type === "Accept");
  }
});

test("concurrent conflicting accept-result calls produce exactly one receipt and one refusal", async () => {
  const dataRoot = root();
  const o = offer("dry-run", dataRoot);
  const product = run(contract(o), "invoke-service", at, { root: dataRoot, liss: lissFixture }).object;
  const [r1, r2] = await Promise.all([
    Promise.resolve(run(decision(product, "Accept", checks(true, "urn:evidence:first")),  "accept-result", at, { root: dataRoot })),
    Promise.resolve(run(decision(product, "Accept", checks(true, "urn:evidence:second")), "accept-result", at, { root: dataRoot })),
  ]);
  const receipts = readdirSync(join(dataRoot, "data", "records", "work-lot-receipts", "2026", "07", "18"));
  assert.equal(receipts.length, 1, "only one receipt must be durably recorded");
  assert.equal([r1, r2].filter((r) => r.type === "Accept").length, 1);
  assert.equal([r1, r2].filter((r) => r.type === "Reject").length, 1);
});
```

Note: `Promise.resolve` wrappers exercise the race path only when implementation I/O yields. True concurrency requires a worker-thread harness; these tests document the invariant and will catch regressions if the implementation is later made async, or if the reservation file is absent.

